<?php
require_once __DIR__.'/../bootstrap/app.php';use GymPro\Services\AttendanceService;require_role('TRAINER');$u=current_user();$sid=(int)($_GET['session_id']??$_POST['session_id']??0);$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{AttendanceService::markClass($sid,(int)$u['TrainerID'],$_POST['status']??[]);set_flash('success','Class attendance saved.');redirect('trainer/attendance.php?session_id='.$sid);}catch(Throwable $e){$errors[]=$e->getMessage();}}
$sessions=db_all("SELECT s.SessionID,s.StartsAt,c.ClassName FROM CLASS_SESSION s JOIN CLASS c ON c.ClassID=s.ClassID WHERE c.TrainerID=? ORDER BY s.StartsAt DESC",'i',[$u['TrainerID']]);$roster=$sid?db_all("SELECT e.EnrollmentID,m.Name,m.MemberNumber,a.Status FROM CLASS_SESSION s JOIN ENROLLMENT e ON e.ClassID=s.ClassID AND e.Status='ENROLLED' JOIN MEMBER m ON m.MemberID=e.MemberID LEFT JOIN CLASS_ATTENDANCE a ON a.SessionID=s.SessionID AND a.EnrollmentID=e.EnrollmentID WHERE s.SessionID=? ORDER BY m.Name",'i',[$sid]):[];$pageTitle='Class attendance';$pageSubtitle='Mark only students enrolled in your session';include ROOT_PATH.'/includes/header.php';?><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><form class="filter-bar" method="get"><label for="session_id" class="sr-only">Class session</label><select id="session_id" name="session_id" required><option value="">Choose a session</option><?php foreach($sessions as $s):?><option value="<?=$s['SessionID']?>" <?=$sid==$s['SessionID']?'selected':''?>><?=e($s['ClassName'])?> — <?=e(date('d M Y H:i',strtotime($s['StartsAt'])))?></option><?php endforeach;?></select><button class="btn btn-ghost">Load roster</button></form><?php if($sid):?><form method="post"><?=csrf_field()?><input type="hidden" name="session_id" value="<?=$sid?>"><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Member</th><th scope="col">Attendance status</th></tr></thead><tbody><?php foreach($roster as $r):?><tr><td><?=e($r['Name'])?><br><small><?=e($r['MemberNumber'])?></small></td><td><label class="sr-only" for="status-<?=$r['EnrollmentID']?>">Status for <?=e($r['Name'])?></label><select id="status-<?=$r['EnrollmentID']?>" name="status[<?=$r['EnrollmentID']?>]"><option value="">Not marked</option><?php foreach(['PRESENT','ABSENT','LATE','EXCUSED'] as $st):?><option <?=$r['Status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></td></tr><?php endforeach;if(!$roster):?><tr><td colspan="2" class="empty-state">No enrolled students.</td></tr><?php endif;?></tbody></table></div><div class="form-actions"><button class="btn btn-primary" type="submit">Save attendance</button></div></form><?php endif;?><?php include ROOT_PATH.'/includes/footer.php';?>
